class Solution {
public:
    bool checkInclusion(string s1, string s2) {
        map<char, int> need, win;
        for (char c : s1) need[c]++;
        int m = s1.size();
        for (int r = 0; r < (int)s2.size(); r++) {
            win[s2[r]]++;
            int l = r - m + 1;
            if (l < 0) continue;
            if (win == need) return true;
            if (--win[s2[l]] == 0) win.erase(s2[l]);
        }
        return false;
    }
};
